/// Loads and exposes the news feed of the home screen.
final class NewsBloc extends Bloc<NewsEvent, NewsState> {
  /// Creates a bloc that fetches news through [repository].
  NewsBloc({required this._repository}) : super(const NewsInitial()) {
    on<NewsStarted>(_onStarted);
  }

  final NewsRepository _repository;

  Future<void> _onStarted(NewsStarted event, Emitter<NewsState> emit) async {
    emit(const NewsLoadInProgress());
    try {
      emit(NewsLoadSuccess(await _repository.fetchNews()));
    } on Object catch (error) {
      emit(NewsLoadFailure(error));
    }
  }
}

import 'package:equatable/equatable.dart';

/// Base class of all news events.
sealed class NewsEvent extends Equatable {
  const NewsEvent();

  @override
  List<Object?> get props => const [];
}

/// Signals that the news feed should be loaded.
final class NewsStarted extends NewsEvent {
  const NewsStarted();
}

import 'package:equatable/equatable.dart';
import 'package:repositories/repositories.dart';

/// Base class of all news states.
sealed class NewsState extends Equatable {
  const NewsState();

  @override
  List<Object?> get props => const [];
}

/// Nothing has been requested yet.
final class NewsInitial extends NewsState {
  const NewsInitial();
}

/// The news feed is being fetched.
final class NewsLoadInProgress extends NewsState {
  const NewsLoadInProgress();
}

/// The news feed has been fetched successfully.
final class NewsLoadSuccess extends NewsState {
  const NewsLoadSuccess(this.news);

  /// The fetched news items, newest first.
  final List<NewsItem> news;

  @override
  List<Object?> get props => [news];
}

/// Fetching the news feed failed.
final class NewsLoadFailure extends NewsState {
  const NewsLoadFailure(this.error);

  /// The error that caused the failure.
  final Object error;

  @override
  List<Object?> get props => [error];
}

import 'package:equatable/equatable.dart';

/// A single entry of the home screen news feed.
final class NewsItem extends Equatable {
  const NewsItem({
    required this.id,
    required this.title,
    required this.imageUrl,
    required this.summary,
    required this.publishedAt,
  });

  /// Unique identifier of the news item.
  final String id;

  /// Headline of the news item.
  final String title;

  /// Path or URL of the item's cover image.
  final String imageUrl;

  /// Short teaser text shown under the title.
  final String summary;

  /// When the item was published.
  final DateTime publishedAt;

  @override
  List<Object?> get props => [id, title, imageUrl, summary, publishedAt];
}

